using FluentValidation;namespace Namaa.Application.Quotations.Commands.AddQuotationPaymentTerm;public sealed class AddQuotationPaymentTermCommandValidator:AbstractValidator<AddQuotationPaymentTermCommand>{public AddQuotationPaymentTermCommandValidator(){RuleFor(x=>x.QuotationId).GreaterThan(0);RuleFor(x=>x).Must(x=>x.Percentage.HasValue||x.Amount.HasValue).WithMessage("Percentage or amount is required.");RuleFor(x=>x.Percentage).InclusiveBetween(0,100).When(x=>x.Percentage.HasValue);RuleFor(x=>x.Amount).GreaterThanOrEqualTo(0).When(x=>x.Amount.HasValue);RuleFor(x=>x.Description).MaximumLength(500);RuleFor(x=>x.DueAfterDays).GreaterThanOrEqualTo(0).When(x=>x.DueAfterDays.HasValue);}}

